// Wave 10 (Task 10.16): the catalog "Your own fields" reads, for tests. Tests only; nothing in the product imports it.
//
// It is the REAL wave 8 server catalog (`serverCatalog.json`, so the sources these tests see stay the three of wave
// 8) with what wave 10 serves for formulas read from the REAL wave 10 catalog (`w10Catalog.json`, generated by
// `tests/test_widget_definitions_router.py::write_vocabulary_fixture`; Task 10.17): the formula `formats`, and per
// field `hourKey` and `needsTimes` exactly as that catalog's same field carries them. Nothing here is typed by hand.
// The functions, the limits and the function docs are NOT here: the builder reads them from the formula twin
// (`lib/widgetFormula`), which the shared vector file binds to the server.
import { CATALOG } from './builderFixtures'
import W10 from './w10Catalog.json'

/** The formula formats the server serves (`[{key, label}]`, be plan.FORMULA_FORMATS with the router's words). */
export const FORMATS = W10.formats

const SERVED = new Map(W10.sources.map((s) => [s.key, new Map(s.fields.map((f) => [f.key, f]))]))

/** A wave 8 field with what wave 10 serves on the same field of the same source. */
function served(sourceKey, f) {
  const w = SERVED.get(sourceKey)?.get(f.key)
  if (!w) return f
  return {
    ...f,
    ...(typeof w.hourKey === 'string' && w.hourKey ? { hourKey: w.hourKey } : {}),
    ...(w.needsTimes === true ? { needsTimes: true } : {}),
  }
}

export const FORMULA_CATALOG = {
  ...CATALOG,
  formats: FORMATS,
  sources: CATALOG.sources.map((s) => ({ ...s, fields: s.fields.map((f) => served(s.key, f)) })),
}
